jobs.content:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;sup&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span&gt;&lt;a href=&quot;https://poly.ai?utm_source=prnewswire&amp;amp;utm_medium=pressrelease&amp;amp;utm_campaign=boilerplate&amp;amp;utm_content=pressrelease&quot; target=&quot;_blank&quot;&gt;PolyAI&lt;/a&gt;&lt;/span&gt; is the Agentic Dialog Platform for building the conversational enterprise, used to build, run, govern, and improve dialog agents at scale. Powered by Raven, a proprietary dialog model trained on more than a billion enterprise conversations, PolyAI agents are built for complexity, open at every layer, and sovereign by design. PolyAI serves hundreds of enterprises across 75 languages and 25 countries, including Metro Bank, Marriott, PG&amp;amp;E, and UniCredit.&lt;/span&gt;&lt;/sup&gt;&lt;/p&gt;&lt;/div&gt;&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;Contract details:&lt;/strong&gt; 6-month contract engagement, with the potential to extend or convert based on business need and performance.&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;The &lt;strong&gt;Field Marketing Manager&lt;/strong&gt; will join PolyAI&#39;s rapidly growing marketing team for a focused 6-month engagement to lead field and ABM event strategy while helping build the foundation for 2027 planning. This role owns events end to end, from strategy and budget through logistics and post-event reporting, and will help establish the reporting structure and planning processes the marketing team uses going forward. This role also serves as a U.S. point of contact for the London-based team.&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;This is a performance-focused role. Events at PolyAI are not just about creative ideas and logistics, they are a pipeline-generating engine that is critical to the overall marketing mix, and this person will be held accountable to that standard.&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;Responsibilities&lt;/strong&gt;&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Own events end to end globally: strategy, budget, logistics, on-site execution, and post-event reporting&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Plan and execute ABM events globally in partnership with sales and marketing stakeholders&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Help build out 2027 marketing planning, including calendar, budget framework, and event strategy&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Set up reporting structures and planning processes for the marketing team&#39;s event and field efforts&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Build and maintain the company events calendar&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Evaluate sponsorship levels for ROI and performance forecasting to guide investment decisions&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Create and manage event timelines using Asana&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Serve as the U.S.-based point of contact for the London team&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Ensure proper tracking of leads and opportunities originating from events, and own reporting on pipeline and revenue generated&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Provide regular analytics reports on the performance of field and event marketing efforts&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Work with thought leaders to identify and secure speaking opportunities&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Build out pre and post event campaigns, treating each event as the centerpiece of a full program, to drive strong attendance and ensure thorough follow-up&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Be AI-fluent and actively work AI tools into day-to-day workflows to move faster on planning, reporting, and campaign execution&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;Minimum Skills and Experience&lt;/strong&gt;&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Interest in working for a fast-growth startup&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Understanding of B2B marketing&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Experience owning events end to end, including ABM events&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Strong project management skills&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Proven track record of being well organized and detail-oriented&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Performance-driven mindset, with experience tying event programs to pipeline and revenue outcomes rather than just execution and logistics&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Comfort setting up reporting and planning processes from scratch&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;AI-fluent, with the ability to incorporate AI tools into everyday workflows&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Willingness to grow and learn&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;Experience organizing trade show booths&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;Experience with Salesforce (SFDC), HubSpot and Claude (or other AI platforms)&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;The salary range for this position is $10,000-$12,000/month. Please note this range is intended as a guide, not a guarantee. Final compensation will be based on individual qualifications, relevant experience, and the scope of the role.&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;hr&gt;
&lt;p style=&quot;line-height: 1.2;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sup&gt;At PolyAI, we take great pride in our values - they guide everything we do. We believe that a strong culture leads to meaningful work and lasting impact.&lt;/sup&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1.2;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sup&gt;Our core values are:&lt;/sup&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sup&gt;&lt;strong&gt;&lt;img style=&quot;max-width: 100%;&quot; src=&quot;https://emoji.slack-edge.com/T8GS4RNNM/only-the-best/63f754d467834139.gif&quot; alt=&quot;:only-the-best:&quot; width=&quot;30&quot;&gt;&lt;br&gt;&lt;/strong&gt;&lt;strong&gt;Only the best&lt;br&gt;&lt;/strong&gt;We expect the best from our people, we hire people that expect the best from themselves, and we nurture this drive for excellence.&lt;/sup&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sup&gt;&lt;strong&gt;&lt;img style=&quot;max-width: 100%;&quot; alt=&quot;&quot;&gt;&lt;img style=&quot;max-width: 100%;&quot; src=&quot;https://emoji.slack-edge.com/T8GS4RNNM/ownership/753f47103884882c.gif&quot; alt=&quot;:ownership:&quot; width=&quot;30&quot;&gt;&lt;br&gt;&lt;/strong&gt;&lt;strong&gt;Ownership&lt;br&gt;&lt;/strong&gt;We care deeply about what we do. We take ownership of our initiatives, decisions and outcomes.&lt;/sup&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sup&gt;&lt;strong&gt;&lt;img style=&quot;max-width: 100%;&quot; src=&quot;https://emoji.slack-edge.com/T8GS4RNNM/relentlessly-improve/b5e1910b7c09b966.gif&quot; alt=&quot;:relentlessly-improve:&quot; width=&quot;30&quot;&gt;&lt;br&gt;&lt;/strong&gt;&lt;strong&gt;Relentlessly improve&lt;br&gt;&lt;/strong&gt;We demand more from ourselves and are always evolving. Continuous, obsessive improvement is the only way we will transform the world of conversational AI.&lt;/sup&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sup&gt;&lt;strong&gt;&lt;img style=&quot;max-width: 100%;&quot; src=&quot;https://emoji.slack-edge.com/T8GS4RNNM/bias-for-action/0a5bd6888d3f2db1.gif&quot; alt=&quot;:bias-for-action:&quot; width=&quot;30&quot;&gt;&lt;br&gt;&lt;/strong&gt;&lt;strong&gt;Bias for action&lt;br&gt;&lt;/strong&gt;Our world moves quickly and so do we. We take calculated risks and we deliver impact fast.&lt;/sup&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sup&gt;&lt;strong&gt;&lt;img style=&quot;max-width: 100%;&quot; src=&quot;https://emoji.slack-edge.com/T8GS4RNNM/disagree-and-commit/0cee7f9f02baac38.gif&quot; alt=&quot;:disagree-and-commit:&quot; width=&quot;30&quot;&gt;&lt;br&gt;Disagree and commit&lt;br&gt;&lt;/strong&gt;We are all working toward the same goal. If we donʼt agree with something, we work hard to understand it and when a decision is made, we accept it and give it our all.&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;&lt;/sup&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sup&gt;&lt;strong&gt;&lt;img style=&quot;max-width: 100%;&quot; src=&quot;https://emoji.slack-edge.com/T8GS4RNNM/build-for-people/9c2fba2ffb2331c8.gif&quot; alt=&quot;:build-for-people:&quot; width=&quot;30&quot;&gt;&lt;br&gt;Build for people&lt;br&gt;&lt;/strong&gt;We want the world to enjoy the experiences they have with us. We are building for a future that prefers automation.&lt;/sup&gt;&lt;/span&gt;&lt;/p&gt;
&lt;hr&gt;
&lt;p style=&quot;line-height: 1.2;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;sup&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif;&quot;&gt;&lt;em&gt;PolyAI is proud to be an equal-opportunity employer. We celebrate diversity and are committed to creating an inclusive environment for all employees. All employment decisions at PolyAI will be based on the business needs without attention to ethnicity, religion, sexual orientation, gender identity, family or parental status, national origin, neurodiversity status or disability status.&lt;/em&gt;&lt;br&gt;&lt;/span&gt;&lt;/sup&gt;&lt;/span&gt;&lt;/p&gt;
&lt;hr&gt;
&lt;p style=&quot;line-height: 1.2;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;sup&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;em&gt;Kindly find the Privacy Notice for our recruitment process by following the link &lt;a href=&quot;https://polyai.notion.site/Recruitment-Privacy-Notice-1b5097db17f7802ead64dd6daf159ded&quot;&gt;here&lt;/a&gt;. This document provides important information regarding how we handle your personal data throughout the recruitment journey.&lt;/em&gt;&lt;/span&gt;&lt;/sup&gt;&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;sup&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span&gt;&lt;a href=&quot;https://poly.ai?utm_source=prnewswire&amp;amp;utm_medium=pressrelease&amp;amp;utm_campaign=boilerplate&amp;amp;utm_content=pressrelease&quot; target=&quot;_blank&quot;&gt;PolyAI&lt;/a&gt;&lt;/span&gt; is the Agentic Dialog Platform for building the conversational enterprise, used to build, run, govern, and improve dialog agents at scale. Powered by Raven, a proprietary dialog model trained on more than a billion enterprise conversations, PolyAI agents are built for complexity, open at every layer, and sovereign by design. PolyAI serves hundreds of enterprises across 75 languages and 25 countries, including Metro Bank, Marriott, PG&amp;amp;E, and UniCredit.&lt;/span&gt;&lt;/sup&gt;&lt;/p&gt;&lt;/div&gt;&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sub&gt;PolyAI is shifting from a sales led motion to a product led growth (PLG) motion. This role owns both the traditional outbound BDR/GTM Specialist team and the emerging PLG lead motion generated through Agent Studio signups.&lt;/sub&gt;&lt;/span&gt;&lt;/p&gt;
&lt;h3 style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;strong&gt;Responsibilities&lt;/strong&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sub&gt;Train and coach GTM Specialists (BDRs) to identify, contact, and create qualified opportunities&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sub&gt;Build the hunting and qualification skills the team needs to work both inbound hand-raisers and outbound prospecting&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sub&gt;Provide recurring weekly 1:1 coaching and feedback to improve rep performance and skills over time&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sub&gt;Own hiring, onboarding, and performance management for the BDR org — including ramp plans, clear performance expectations, and acting decisively when reps aren&#39;t tracking&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sub&gt;Work the Agent Studio self-serve signup base as a prospecting surface identify which signups sit inside enterprise and mid-market accounts and qualify them into sales opportunities&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sub&gt;Build the feedback loop that sharpens behavioral scoring so the PLG model gets better at surfacing enterprise and mid-market fit over time&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sub&gt;Monitor team performance against targets and present accurate, timely reports and forecasts of weekly, monthly, and quarterly attainment&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sub&gt;Work closely with Demand Gen on MQL quality and campaign feedback&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sub&gt;Work closely with Sales and Leadership to improve opportunity management and qualification processes&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sub&gt;Collaborate with marketing content, program managers, product marketing, and sales directors to develop messaging that converts inbound and outbound interest into qualified pipeline&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sub&gt;Evaluate compensation structure to ensure it rewards pipeline quality and conversion outcomes rather than activity volume, and own ongoing comp program administration&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sub&gt;Build succession planning and career paths for the team&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;sub&gt;Present accurate, timely performance reports and forecasts (weekly, monthly, quarterly)&lt;/sub&gt;&lt;/span&gt;&lt;/li&gt;
